{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "version",
    "nativeFamily",
    "system",
    "grants",
    "cold",
    "cancel",
    "box"
  ],
  "properties": {
    "version": {
      "const": 1
    },
    "nativeFamily": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "handoffCapacityBytes",
        "handoffReleaseBytes"
      ],
      "properties": {
        "handoffCapacityBytes": {
          "const": 0
        },
        "handoffReleaseBytes": {
          "const": 0
        }
      }
    },
    "system": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "constructorCapacityBytes",
        "cancelCapacityBytes",
        "cancelReleaseBytes",
        "handoffCapacityBytes",
        "handoffReleaseBytes",
        "turnCapacityBytes"
      ],
      "properties": {
        "constructorCapacityBytes": {
          "const": 0
        },
        "cancelCapacityBytes": {
          "const": 0
        },
        "cancelReleaseBytes": {
          "const": 0
        },
        "handoffCapacityBytes": {
          "const": 0
        },
        "handoffReleaseBytes": {
          "const": 0
        },
        "turnCapacityBytes": {
          "const": 0
        }
      }
    },
    "grants": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "items",
        "bytes"
      ],
      "properties": {
        "items": {
          "const": 1
        },
        "bytes": {
          "const": 8
        }
      }
    },
    "cold": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "initialEdges",
        "initialFaces",
        "initialUnits",
        "callerProbeTurns"
      ],
      "properties": {
        "initialEdges": {
          "const": 0
        },
        "initialFaces": {
          "const": 0
        },
        "initialUnits": {
          "const": 0
        },
        "callerProbeTurns": {
          "const": 8
        }
      }
    },
    "cancel": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "releasesAtSignal",
        "releasesBeforeCredit",
        "sampleReleases",
        "meshReleases"
      ],
      "properties": {
        "releasesAtSignal": {
          "const": 0
        },
        "releasesBeforeCredit": {
          "const": 0
        },
        "sampleReleases": {
          "const": 1
        },
        "meshReleases": {
          "const": 1
        }
      }
    },
    "box": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "faces",
        "edges",
        "triangles",
        "area",
        "volume"
      ],
      "properties": {
        "faces": {
          "const": 6
        },
        "edges": {
          "const": 12
        },
        "triangles": {
          "const": 12
        },
        "area": {
          "const": 6
        },
        "volume": {
          "const": 1
        }
      }
    }
  }
}

import { test, expect } from "bun:test";
import { readFileSync } from "node:fs";
import Ajv2020 from "ajv/dist/2020";
import { BoxGeometry, Triangle, Vector3 } from "three";

/** 🎟️ Independent geometry oracle for the original retained tessellation laws. */
test("original tessellation grants and unit-box parity agree with Three", () => {
  const fixture=JSON.parse(readFileSync(new URL("../../🧫️fixtures/🎟️ownership/🔣️.json",import.meta.url),"utf8"));
  const schema=JSON.parse(readFileSync(new URL("../../🧫️fixtures/🎟️ownership/🧬️schema/🔣️.json",import.meta.url),"utf8"));
  expect(new Ajv2020({strict:true}).compile(schema)(fixture)).toBe(true);
  const geometry=new BoxGeometry(1,1,1);const position=geometry.getAttribute("position");const index=geometry.getIndex()!;
  let area=0,volume=0;const corners:[Vector3,Vector3,Vector3]=[new Vector3(),new Vector3(),new Vector3()];
  for(let cursor=0;cursor<index.count;cursor+=3){corners.forEach((point,offset)=>point.fromBufferAttribute(position,index.getX(cursor+offset)));area+=new Triangle(...corners).getArea();volume+=corners[0].dot(corners[1].clone().cross(corners[2]))/6;}
  expect(area).toBe(fixture.box.area);expect(Math.abs(volume)).toBeCloseTo(fixture.box.volume,12);expect(index.count/3).toBe(fixture.box.triangles);geometry.dispose();
  console.log("[DEBUG] Original tessellation neutral ownership fixture: independent Three area=6 volume=1 triangles=12");
});
